import random, sys
import selfies as sf
from selfies.utils.smiles_utils import smiles_to_mol

def graph_signature(smiles):
    mol = smiles_to_mol(smiles, attributable=False)
    assert mol.kekulize()
    atoms = []
    for a in mol.get_atoms():
        atoms.append((a.element, a.isotope, a.charge, a.h_count))
    bonds = set()
    for a in mol.get_atoms():
        for b in mol.get_out_dirbonds(a.index):
            bonds.add((min(b.src, b.dst), max(b.src, b.dst), b.order))
    return atoms, sorted(bonds)

random.seed(0)
alpha = sorted(sf.get_semantic_robust_alphabet())
bad = 0
for trial in range(3000):
    n = random.randint(1, 20)
    s = "".join(random.choice(alpha) for _ in range(n))
    try:
        smi = sf.decoder(s)
    except Exception as e:
        print("DECODE FAIL", s, type(e).__name__, e); bad += 1; continue
    try:
        re_sel = sf.encoder(smi)
        smi2 = sf.decoder(re_sel)
    except Exception as e:
        print("ROUNDTRIP FAIL", s, "->", smi, type(e).__name__, str(e).splitlines()[0]); bad += 1; continue
    try:
        g1, g2 = graph_signature(smi), graph_signature(smi2)
    except Exception as e:
        print("PARSE FAIL", smi, smi2, e); bad += 1; continue
    if g1 != g2:
        print("MISMATCH", s, smi, smi2); bad += 1
print("bad:", bad)
