"""Check the Kekule-structure invariants directly on the molecular graphs."""
import json
import selfies as sf
from selfies.utils.smiles_utils import smiles_to_mol

corpus = json.load(open("/tmp/corpus.json"))
checked = viol = 0
for smi in corpus:
    try:
        mol = smiles_to_mol(smi, attributable=False)
    except Exception:
        continue
    ds = {n: list(adj) for n, adj in mol._delocal_subgraph.items()}
    required = {n for n in ds if not mol._prune_from_ds(n)}
    optional = {n for n in ds if n not in required and mol._can_make_ds_bond(n)}
    if not mol.kekulize():
        continue
    checked += 1
    dbl = {n: 0 for n in ds}
    for n, adjs in ds.items():
        for a in adjs:
            order = mol.get_dirbond(min(n, a), max(n, a)).order
            if order not in (1, 2):
                print("BAD ORDER", smi, order); viol += 1
            if order == 2:
                dbl[n] += 1
    for n in ds:
        if n in required and dbl[n] != 1:
            print("REQUIRED NOT MATCHED ONCE", smi, n, dbl[n]); viol += 1; break
        if n not in required and dbl[n] > 1:
            print("DOUBLE MATCHED", smi, n, dbl[n]); viol += 1; break
        if (n not in required) and (n not in optional) and dbl[n] != 0:
            print("PRUNED GOT BOND", smi, n); viol += 1; break
print("kekulized molecules checked:", checked, " invariant violations:", viol)
